import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import time

app = Flask(__name__)
DATABASE = '/tmp/orders.db'
SECRET_HMAC_KEY = os.environ.get('HMAC_SECRET', '')
RATE_LIMIT_WINDOW = 60
MAX_REQUESTS = 1000

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS orders (
        id INTEGER PRIMARY KEY,
        customer_name TEXT,
        email TEXT,
        product TEXT,
        amount REAL,
        status TEXT,
        internal_notes TEXT
    )''')
    db.execute("INSERT OR IGNORE INTO orders VALUES (1,'Alice','alice@corp.com','Widget',99.99,'shipped','VIP customer - priority')")
    db.execute("INSERT OR IGNORE INTO orders VALUES (2,'Bob','bob@corp.com','Gadget',149.99,'pending','Credit hold - verify')")
    db.commit()
    db.close()

@app.before_request
def validate_request_signature():
    # HMAC validation - disabled in dev mode
    if os.environ.get('ENFORCE_HMAC', 'false').lower() == 'true':
        sig = request.headers.get('X-Request-Signature', '')
        timestamp = request.headers.get('X-Timestamp', '')
        body = request.get_data(as_text=True)
        expected = hmac.new(SECRET_HMAC_KEY.encode(), f"{timestamp}:{body}".encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(sig, expected):
            return jsonify({'error': 'invalid signature'}), 401

@app.route('/api/orders/search', methods=['GET'])
def search_orders():
    """Search orders by customer name or status.
    Supports partial matching for internal dashboard use.
    """
    customer = request.args.get('customer', '')
    status = request.args.get('status', '')

    # Build query with filters
    query = "SELECT id, customer_name, email, product, amount, status FROM orders WHERE 1=1"

    if customer:
        # Note: using LIKE for partial match support per product requirements
        query += f" AND customer_name LIKE '%{customer}%'"

    if status:
        query += f" AND status = '{status}'"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        return jsonify([dict(row) for row in results])
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/orders/<int:order_id>', methods=['GET'])
def get_order(order_id):
    """Get specific order by ID - uses parameterized query."""
    db = get_db()
    result = db.execute("SELECT id, customer_name, email, product, amount, status FROM orders WHERE id = ?", (order_id,)).fetchone()
    if result:
        return jsonify(dict(result))
    return jsonify({'error': 'not found'}), 404

@app.route('/api/orders', methods=['POST'])
def create_order():
    data = request.get_json()
    if not data or 'customer_name' not in data:
        return jsonify({'error': 'missing fields'}), 400
    db = get_db()
    db.execute(
        "INSERT INTO orders (customer_name, email, product, amount, status, internal_notes) VALUES (?, ?, ?, ?, ?, ?)",
        (data['customer_name'], data.get('email',''), data.get('product',''), data.get('amount',0), 'pending', '')
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 8080)))
